def solve_torus_coloring(P):
    """
    Finds the chromatic number of the King's graph on a PxP torus.
    """

    # 1. Define the adjacency graph
    nodes = [(i, j) for i in range(P) for j in range(P)]
    N = P * P
    adj = {node: set() for node in nodes}

    def toroidal_distance(p1, p2):
        dx = abs(p1[0] - p2[0])
        dy = abs(p1[1] - p2[1])
        return min(dx, P - dx), min(dy, P - dy)

    for i in range(N):
        for j in range(i + 1, N):
            u = nodes[i]
            v = nodes[j]

            # Check if they are neighbors (King's move distance <= 1 in both dimensions)
            d_x, d_y = toroidal_distance(u, v)
            if d_x <= 1 and d_y <= 1:
                adj[u].add(v)
                adj[v].add(u)

    # 2. Backtracking search for minimum colors (Chromatic Number)

    def is_safe(node, color, coloring):
        """Checks if assigning 'color' to 'node' is valid given current coloring."""
        for neighbor in adj[node]:
            if neighbor in coloring and coloring[neighbor] == color:
                return False
        return True

    def graph_coloring_util(k, coloring, max_colors):
        """Tries to color the graph using up to max_colors."""
        if k == N:
            return True  # All nodes colored

        node = nodes[k]

        for color in range(1, max_colors + 1):
            if is_safe(node, color, coloring):
                coloring[node] = color
                if graph_coloring_util(k + 1, coloring, max_colors):
                    return True
                del coloring[node] # Backtrack

        return False

    # Start checking from 1 color upwards
    for c in range(1, N + 1):
        initial_coloring = {}
        if graph_coloring_util(0, initial_coloring, c):
            return c

    return N # Should not happen

